/* --------------------------------------------------------------------------
   BASE RESET & LAYOUT
   -------------------------------------------------------------------------- */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-main);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  transition: background-color 0.4s ease, color 0.4s ease;
}

/* Particle Canvas for V4 Quantum Theme */
#quantumCanvas {
  position: fixed;
  top: 0;
  left: 0;
